// GRASS on the WebGL fallback — the CPU-placement approximation of
// grass3d.ts's compute-spawned blade field (the plan's prescribed route: the
// spawn kernels are compute-bound; the blade GEOMETRY + SHADING port intact).
//
// Every frame a CPU pass walks the camera-following spawn lattice and packs
// one Blade record per surviving cell — the SAME per-cell maths as
// bladeComputeWGSL (sin-hash jitter, grassy-colormap gate, keep-probability
// thinning, edge fade, height/width/tint variation), so the field LOOKS like
// the original's near carpet; blades are pinned to world cells and never
// swim. Deltas vs WebGPU (report-worthy):
//   - the lattice is COARSER (default 224² vs 320²) and hard-capped at
//     40k blades — density is ~half the WebGPU carpet;
//   - the far billboard CARD ring IS ported (the clump/flower texture bake
//     was always canvas/CPU — reused verbatim): a 128² far lattice walked per
//     frame, capped at 16k cards (vs the compute field's 300² eternal
//     residents), so the far carpet is sparser; flowers ride the same frames;
//   - the fan window (viewBias/fanAngle) is not implemented (full disc);
//   - frustum culling is per-blade on the CPU (sphereVsFrustum).
// The colormap gate samples the terrain's CPU-retained band pixels — the
// same bake the GPU texture holds, so blades grow on exactly the ground the
// WebGPU field would pick.
//
// Module load is DOM/GL-free.

import { rgba } from '../color.js';
import { sphereVsFrustum } from '../math3d.js';
import type { GrassOptions } from '../grass3d.js';
import { compileProgram, instanceVec4Attribs, InstanceBuffer } from '../webgl/shaders.js';
import {
  buildGlGrassVertGLSL, buildGlGrassFragGLSL,
  buildGlGrassCardVertGLSL, buildGlGrassCardFragGLSL,
  GRASS_BLADE_FLOATS, GRASS_BLADE_VERTS,
} from './shaders3d.js';

const MAX_BLADES = 40_000;
const MAX_CARDS = 16_000;
const CARD_CELLS = 128;   // far lattice per side (vs the compute field's 300)

/** The sin-hash pair — bladeComputeWGSL's hash2/rand, ported exactly so the
 * CPU field reproduces the GPU distribution. */
function hash2x(px: number, pz: number): number {
  return fract(Math.sin(px * 127.1 + pz * 311.7) * 43758.5453);
}
function hash2y(px: number, pz: number): number {
  return fract(Math.sin(px * 269.5 + pz * 183.3) * 43758.5453);
}
function rand2(px: number, pz: number): number {
  return fract(Math.sin(px * 419.2 + pz * 71.9) * 43758.5453);
}
const fract = (v: number): number => v - Math.floor(v);
const smooth01 = (e0: number, e1: number, x: number): number => {
  const t = Math.min(1, Math.max(0, (x - e0) / (e1 - e0)));
  return t * t * (3 - 2 * t);
};

interface GrassProg { p: WebGLProgram | null; u: Record<string, WebGLUniformLocation | null> }

/** Per-frame uniforms the blade program consumes (world.ts's FrameU is a
 * structural superset). */
export interface GrassFrameU {
  vp: Float32Array;
  camPos: readonly number[];
  fogColor: readonly number[];
  params: readonly number[];
  lightDir: readonly number[];
  right: readonly number[];
  ambSky: readonly number[];
  ambGround: readonly number[];
  sunCol: readonly number[];
}

/** A follow-window blade field bound to one terrain — the GL Grass3d. */
export class GlGrass3d {
  /** Live dials (grass3d parity where portable). */
  showBlades = true;
  /** Straw/hay recolour 0..1 — live. */
  dryness = 0;
  dead = false;

  readonly span: number;
  readonly cells: number;
  private height: number;
  private width: number;
  private windDir: number;
  private windStr: number;
  private dynamic: number;
  private groundTint: number;
  private green: [number, number, number];
  /** Far billboard cards (grass3d parity where portable). */
  showCards = true;
  /** Fraction of the field that flowers (drift-gated). Live-mutable. */
  flowerAmount = 0;
  private farSpan: number;
  private cardW: number;
  private cardH: number;
  private flowerCount: number;
  private cardFrames = 1;

  private gl!: WebGL2RenderingContext;
  private prog: GrassProg = { p: null, u: {} };
  private vao: WebGLVertexArrayObject | null = null;
  private inst!: InstanceBuffer;
  private data = new Float32Array(MAX_BLADES * GRASS_BLADE_FLOATS);
  private count = 0;
  private cardProg: GrassProg = { p: null, u: {} };
  private cardVao: WebGLVertexArrayObject | null = null;
  private cardInst!: InstanceBuffer;
  private cardData = new Float32Array(MAX_CARDS * GRASS_BLADE_FLOATS);
  private cardCount = 0;
  private cardTex: WebGLTexture | null = null;

  constructor(
    gl: WebGL2RenderingContext,
    private readonly field: { heights: Float32Array; res: number; size: number },
    private readonly colormap: { pixels: Uint8ClampedArray; res: number },
    opts: GrassOptions = {},
  ) {
    this.span = opts.span ?? 44;
    // Coarser than the WebGPU 320² lattice — the CPU walks this every frame.
    this.cells = Math.min(opts.cells ?? 224, 288);
    this.dynamic = opts.dynamic ?? 0.5;
    this.height = opts.height ?? 1.1;
    this.width = opts.width ?? 0.03;
    this.windDir = opts.windDir ?? 0.6;
    this.windStr = opts.wind ?? 0.25;
    this.groundTint = opts.groundTint ?? 0.3;
    const c = rgba(opts.color ?? '#6db544');
    this.green = [c[0], c[1], c[2]];
    this.farSpan = opts.farSpan ?? 360;
    this.cardW = opts.cardWidth ?? 0.7;
    this.cardH = opts.cardHeight ?? this.height;   // blade-height cards (the lawnmower lesson)
    this.flowerCount = Math.max(0, Math.round(opts.flowers ?? 0));
    this.rebuild(gl);
  }

  rebuild(gl: WebGL2RenderingContext): void {
    this.gl = gl;
    this.vao = null;
    this.inst = new InstanceBuffer(gl);
    const p = compileProgram(gl, buildGlGrassVertGLSL(), buildGlGrassFragGLSL(), 'GlGrass3d blades');
    const u: Record<string, WebGLUniformLocation | null> = {};
    if (p) {
      for (const name of ['uViewProj', 'uParams', 'uWind', 'uCamPos', 'uFogColor', 'uLightDir', 'uAmbSky', 'uAmbGround', 'uSunCol']) {
        u[name] = gl.getUniformLocation(p, name);
      }
    }
    this.prog = { p, u };
    const cp = compileProgram(gl, buildGlGrassCardVertGLSL(), buildGlGrassCardFragGLSL(), 'GlGrass3d cards');
    const cu: Record<string, WebGLUniformLocation | null> = {};
    if (cp) {
      for (const name of ['uViewProj', 'uParams', 'uWind', 'uRight', 'uCamPos', 'uFogColor', 'uLightDir', 'uAmbSky', 'uAmbGround', 'uSunCol']) {
        cu[name] = gl.getUniformLocation(cp, name);
      }
      gl.useProgram(cp);
      const loc = gl.getUniformLocation(cp, 'uCardTex');
      if (loc) gl.uniform1i(loc, 0);
    }
    this.cardProg = { p: cp, u: cu };
    this.cardVao = null;
    this.cardInst = new InstanceBuffer(gl);
    this.cardTex = this.makeCardTexture();
  }

  // ── The clump texture bake — grass3d.ts's makeCardTexture/drawGrassClump/
  // drawFlowerClump, duplicated (private there; pure canvas/CPU). Uploaded
  // as an SRGB TEXTURE_2D_ARRAY with generateMipmap (GL has auto-gen; the
  // WebGPU CPU halving existed only because WebGPU doesn't). ───────────────

  private makeCardTexture(): WebGLTexture | null {
    if (typeof document === 'undefined') return null;
    const gl = this.gl;
    const S = 256;
    const bake = (draw: (ctx: CanvasRenderingContext2D, rnd: () => number) => void, fill: [number, number, number], seed0 = 1234.5): Uint8Array => {
      const cv = document.createElement('canvas');
      cv.width = cv.height = S;
      const ctx = cv.getContext('2d')!;
      ctx.clearRect(0, 0, S, S);
      let seed = seed0;
      const rnd = (): number => { seed = (seed * 16807 + 7) % 2147483647; return (seed % 10000) / 10000; };
      draw(ctx, rnd);
      // Colour DILATION into transparent pixels (mip-safe silhouettes).
      const px = ctx.getImageData(0, 0, S, S).data;
      for (let i = 0; i < px.length; i += 4) {
        const a = px[i + 3] / 255;
        px[i] = px[i] * a + fill[0] * (1 - a);
        px[i + 1] = px[i + 1] * a + fill[1] * (1 - a);
        px[i + 2] = px[i + 2] * a + fill[2] * (1 - a);
      }
      return new Uint8Array(px.buffer.slice(0));
    };
    const layers: Uint8Array[] = [bake((ctx, rnd) => this.drawGrassClump(ctx, S, rnd), [46, 92, 38])];
    for (let f = 0; f < this.flowerCount; f++) {
      layers.push(bake((ctx, rnd) => this.drawFlowerClump(ctx, S, rnd, f), [46, 92, 38], 811.3 + f * 131.7));
    }
    this.cardFrames = layers.length;
    const tex = gl.createTexture()!;
    gl.bindTexture(gl.TEXTURE_2D_ARRAY, tex);
    const mips = 1 + Math.floor(Math.log2(S));
    gl.texStorage3D(gl.TEXTURE_2D_ARRAY, mips, gl.SRGB8_ALPHA8, S, S, layers.length);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
    gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
    layers.forEach((lvl0, layer) => {
      gl.texSubImage3D(gl.TEXTURE_2D_ARRAY, 0, 0, 0, layer, S, S, 1, gl.RGBA, gl.UNSIGNED_BYTE, lvl0);
    });
    gl.generateMipmap(gl.TEXTURE_2D_ARRAY);
    gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
    gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    return tex;
  }

  /** Grass CLUMP silhouette — grass3d.drawGrassClump, verbatim. */
  private drawGrassClump(ctx: CanvasRenderingContext2D, S: number, rnd: () => number): void {
    const blades = 17;
    for (let i = 0; i < blades; i++) {
      const bx = (0.1 + rnd() * 0.8) * S;
      const topY = (0.02 + rnd() * 0.35) * S;
      const w = (0.018 + rnd() * 0.028) * S;
      const bend = (rnd() - 0.5) * 0.3 * S;
      const g0 = ctx.createLinearGradient(0, S, 0, topY);
      const lum = 0.55 + rnd() * 0.3;
      g0.addColorStop(0, `rgba(${34 * lum | 0}, ${70 * lum | 0}, ${28 * lum | 0}, 1)`);
      g0.addColorStop(1, `rgba(${120 * lum | 0}, ${180 * lum | 0}, ${70 * lum | 0}, 1)`);
      ctx.fillStyle = g0;
      ctx.beginPath();
      ctx.moveTo(bx - w, S);
      ctx.lineTo(bx + w, S);
      ctx.quadraticCurveTo(bx + bend * 0.5, (S + topY) * 0.5, bx + bend, topY);
      ctx.closePath();
      ctx.fill();
    }
  }

  /** FLOWER cluster — grass3d.drawFlowerClump, verbatim (albedo petals). */
  private drawFlowerClump(ctx: CanvasRenderingContext2D, S: number, rnd: () => number, variant: number): void {
    for (let i = 0; i < 8; i++) {
      const bx = (0.12 + rnd() * 0.76) * S;
      const topY = (0.28 + rnd() * 0.32) * S;
      const w = (0.014 + rnd() * 0.02) * S;
      const bend = (rnd() - 0.5) * 0.24 * S;
      const lum = 0.5 + rnd() * 0.25;
      ctx.fillStyle = `rgba(${40 * lum | 0}, ${86 * lum | 0}, ${34 * lum | 0}, 1)`;
      ctx.beginPath();
      ctx.moveTo(bx - w, S);
      ctx.lineTo(bx + w, S);
      ctx.quadraticCurveTo(bx + bend * 0.5, (S + topY) * 0.5, bx + bend, topY);
      ctx.closePath();
      ctx.fill();
    }
    const palettes: Array<{ petal: [number, number, number]; centre: [number, number, number]; petals: number; r: number }> = [
      { petal: [214, 42, 34], centre: [30, 18, 12], petals: 5, r: 0.11 },
      { petal: [244, 244, 232], centre: [240, 198, 44], petals: 12, r: 0.085 },
      { petal: [78, 96, 214], centre: [40, 40, 70], petals: 8, r: 0.075 },
      { petal: [248, 208, 44], centre: [200, 150, 24], petals: 8, r: 0.09 },
      { petal: [226, 118, 176], centre: [230, 220, 90], petals: 6, r: 0.09 },
      { petal: [178, 96, 214], centre: [236, 214, 80], petals: 7, r: 0.08 },
    ];
    const pal = palettes[variant % palettes.length];
    const heads = 3 + ((rnd() * 4) | 0);
    for (let h = 0; h < heads; h++) {
      const hx = (0.2 + rnd() * 0.6) * S;
      const hy = (0.08 + rnd() * 0.34) * S;
      const r = pal.r * S * (0.8 + rnd() * 0.5);
      ctx.strokeStyle = 'rgba(46, 96, 40, 1)';
      ctx.lineWidth = 0.012 * S;
      ctx.beginPath();
      ctx.moveTo(hx + (rnd() - 0.5) * 0.06 * S, S);
      ctx.quadraticCurveTo(hx, (hy + S) * 0.5, hx, hy);
      ctx.stroke();
      ctx.fillStyle = `rgb(${pal.petal[0]}, ${pal.petal[1]}, ${pal.petal[2]})`;
      for (let p = 0; p < pal.petals; p++) {
        const a = (p / pal.petals) * Math.PI * 2 + rnd() * 0.2;
        ctx.save();
        ctx.translate(hx, hy);
        ctx.rotate(a);
        ctx.beginPath();
        ctx.ellipse(0, -r * 0.72, r * 0.34, r * 0.72, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
      ctx.fillStyle = `rgb(${pal.centre[0]}, ${pal.centre[1]}, ${pal.centre[2]})`;
      ctx.beginPath();
      ctx.arc(hx, hy, r * 0.42, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  /** Terrain height — the baked-heightfield bilinear the compute used
   * (dim = res+1; texel i ↔ world (i/res − 0.5)·size). */
  private groundAt(wx: number, wz: number): number {
    const res = this.field.res;
    const h = this.field.heights;
    const fx = (wx / this.field.size + 0.5) * res;
    const fz = (wz / this.field.size + 0.5) * res;
    const x0 = Math.min(Math.max(Math.floor(fx), 0), res);
    const z0 = Math.min(Math.max(Math.floor(fz), 0), res);
    const x1 = Math.min(x0 + 1, res);
    const z1 = Math.min(z0 + 1, res);
    const tx = fx - Math.floor(fx), tz = fz - Math.floor(fz);
    const dim = res + 1;
    const a = h[z0 * dim + x0], b = h[z0 * dim + x1];
    const cc = h[z1 * dim + x0], d = h[z1 * dim + x1];
    return (a + (b - a) * tx) + ((cc + (d - cc) * tx) - (a + (b - a) * tx)) * tz;
  }

  /** CPU SPAWN — bladeComputeWGSL's per-cell maths over the follow lattice,
   * packing surviving blades (≤ MAX_BLADES) for one instanced draw. */
  spawn(camX: number, camY: number, camZ: number, planes: Float32Array | null): void {
    this.count = 0;
    if (!this.showBlades) return;
    const cells = this.cells;
    const spacing = this.span / cells * (320 / cells) * cells / (320 / 1); // see below
    // Spacing matches the ORIGINAL field density definition: span/cells of
    // the WebGPU lattice — a coarser GL lattice therefore covers the same
    // span with wider cells (fewer, evenly spread blades, not a smaller rug).
    const cellW = this.span / cells;
    void spacing;
    const halfSpan = this.span * 0.5;
    const ox = Math.floor(camX / cellW) - cells * 0.5;
    const oz = Math.floor(camZ / cellW) - cells * 0.5;
    const ext = this.field.size * 0.5;
    const cm = this.colormap;
    const d = this.data;
    for (let iz = 0; iz < cells; iz++) {
      const wcz = oz + iz;
      for (let ix = 0; ix < cells; ix++) {
        const wcx = ox + ix;
        const jx = hash2x(wcx, wcz), jy = hash2y(wcx, wcz);
        const bx = (wcx + 0.5 + (jx - 0.5) * 0.9) * cellW;
        const bz = (wcz + 0.5 + (jy - 0.5) * 0.9) * cellW;
        const dx = bx - camX, dz = bz - camZ;
        const dist = Math.sqrt(dx * dx + dz * dz);
        if (dist > halfSpan) continue;
        if (Math.abs(bx) > ext || Math.abs(bz) > ext) continue;
        // keepProb: dynamic fraction × the distance thinning (verbatim).
        const keepProb = this.dynamic * (1 + (0.12 - 1) * smooth01(halfSpan * 0.3, halfSpan, dist));
        if (rand2(wcx * 7.1, wcz * 3.3) > keepProb) continue;
        // Grassy-ground gate off the CPU colormap pixels.
        const tu = Math.min(Math.max((bx / this.field.size + 0.5) * cm.res, 0), cm.res - 1) | 0;
        const tv = Math.min(Math.max((bz / this.field.size + 0.5) * cm.res, 0), cm.res - 1) | 0;
        const pi = (tv * cm.res + tu) * 4;
        const br = cm.pixels[pi] / 255, bg = cm.pixels[pi + 1] / 255, bb = cm.pixels[pi + 2] / 255;
        const grassy = smooth01(0, 0.05, bg - Math.max(br, bb));
        if (grassy < 0.25) continue;
        const gy = this.groundAt(bx, bz);
        // Height taper with distance (sparser AND shorter toward the edge).
        const edgeFade = smooth01(halfSpan, halfSpan * 0.35, dist);
        const hgt = this.height * (0.6 + rand2(wcz, wcx) * 0.7) * grassy * edgeFade;
        if (hgt < 0.03) continue;
        // CPU frustum cull (replaces the kernel's NDC test).
        if (planes && !sphereVsFrustum(planes, bx, gy + hgt * 0.5, bz, hgt)) continue;
        const yaw = jx * 6.28318 + rand2(wcx * 1.3, wcz) * 0.6;
        const bend = 0.1 + jy * 0.22;
        const wdt = this.width * (0.6 + rand2(wcx * 5.3, wcz) * 0.9);
        const hueV = (rand2(wcx * 2.7, wcz * 1.9) - 0.5) * 0.12;
        const bright = 0.82 + rand2(wcx, wcz * 2.1) * 0.36;
        const gt = this.groundTint;
        const r = Math.max(0, (this.green[0] * (1 - gt) + br * gt) * bright + hueV * 0.5);
        const g = Math.max(0, (this.green[1] * (1 - gt) + bg * gt) * bright + hueV);
        const bl = Math.max(0, (this.green[2] * (1 - gt) + bb * gt) * bright - hueV * 0.5);
        const phase = rand2(wcz * 3.7, wcx) * 6.28318;
        const o = this.count * GRASS_BLADE_FLOATS;
        d[o] = bx; d[o + 1] = gy; d[o + 2] = bz; d[o + 3] = hgt;
        d[o + 4] = Math.sin(yaw); d[o + 5] = Math.cos(yaw); d[o + 6] = bend; d[o + 7] = wdt;
        d[o + 8] = r; d[o + 9] = g; d[o + 10] = bl; d[o + 11] = phase;
        this.count++;
        if (this.count >= MAX_BLADES) { iz = cells; break; }
      }
    }
    void camY;
    this.spawnCards(camX, camZ, planes);
  }

  /** Low-frequency value noise (cardComputeWGSL's vnoise — flower drifts). */
  private vnoise(x: number, y: number): number {
    const ix = Math.floor(x), iy = Math.floor(y);
    const fx = x - ix, fy = y - iy;
    const ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy);
    const a = rand2(ix, iy), b = rand2(ix + 1, iy);
    const c = rand2(ix, iy + 1), d = rand2(ix + 1, iy + 1);
    return a + (b - a) * ux + (c - a) * uy + (a - b - c + d) * ux * uy;
  }

  /** CPU card spawn — cardComputeWGSL's per-cell maths over a coarser far
   * lattice (128² vs 300²), capped at 16k. Existence is WORLD-anchored
   * (grassy ground + far-edge taper only — no camera terms, the flicker/mow
   * lesson); the frustum cull applies only past 30u like the original. */
  private spawnCards(camX: number, camZ: number, planes: Float32Array | null): void {
    this.cardCount = 0;
    if (!this.showCards || !this.cardTex) return;
    const cells = CARD_CELLS;
    const spacing = this.farSpan / cells;
    const halfSpan = this.farSpan * 0.5;
    const ox = Math.floor(camX / spacing) - cells * 0.5;
    const oz = Math.floor(camZ / spacing) - cells * 0.5;
    const ext = this.field.size * 0.5;
    const cm = this.colormap;
    const d = this.cardData;
    const fl = this.cardFrames - 1;
    for (let iz = 0; iz < cells; iz++) {
      const wcz = oz + iz;
      for (let ix = 0; ix < cells; ix++) {
        const wcx = ox + ix;
        const jx = hash2x(wcx * 1.7, wcz * 2.3), jy = hash2y(wcx * 1.7, wcz * 2.3);
        const bx = (wcx + 0.5 + (jx - 0.5) * 0.9) * spacing;
        const bz = (wcz + 0.5 + (jy - 0.5) * 0.9) * spacing;
        const dx = bx - camX, dz = bz - camZ;
        const dist = Math.sqrt(dx * dx + dz * dz);
        if (dist > halfSpan) continue;
        if (Math.abs(bx) > ext || Math.abs(bz) > ext) continue;
        const tu = Math.min(Math.max((bx / this.field.size + 0.5) * cm.res, 0), cm.res - 1) | 0;
        const tv = Math.min(Math.max((bz / this.field.size + 0.5) * cm.res, 0), cm.res - 1) | 0;
        const pi = (tv * cm.res + tu) * 4;
        const br = cm.pixels[pi] / 255, bg = cm.pixels[pi + 1] / 255, bb = cm.pixels[pi + 2] / 255;
        const grassy = smooth01(0, 0.05, bg - Math.max(br, bb));
        if (grassy < 0.25) continue;
        const keepP = grassy * (1 - smooth01(halfSpan * 0.85, halfSpan, dist));
        if (rand2(wcx * 9.3, wcz * 5.7) > keepP) continue;
        const gy = this.groundAt(bx, bz);
        const hgt = this.cardH * (0.7 + rand2(wcz * 2.2, wcx) * 0.6);
        if (planes && dist > 30 && !sphereVsFrustum(planes, bx, gy + hgt * 0.5, bz, hgt * 2)) continue;
        const wdt = this.cardW * (0.7 + rand2(wcx * 3.1, wcz) * 0.6);
        const hueV = (rand2(wcx * 2.7, wcz * 1.9) - 0.5) * 0.1;
        const gt = Math.max(this.groundTint, 0.35);
        const bright = 0.82 + rand2(wcx, wcz) * 0.32;
        const r = Math.max(0, (this.green[0] * (1 - gt) + br * gt) * bright + hueV * 0.5);
        const g = Math.max(0, (this.green[1] * (1 - gt) + bg * gt) * bright + hueV);
        const bl = Math.max(0, (this.green[2] * (1 - gt) + bb * gt) * bright - hueV * 0.5);
        let frame = 0;
        if (fl > 0 && this.flowerAmount > 0.001) {
          const drift = this.vnoise(bx * 0.05, bz * 0.05);
          if (drift > 1 - this.flowerAmount && rand2(wcx * 5.9, wcz * 8.1) < 0.5) {
            frame = 1 + ((rand2(wcz * 1.3, wcx * 4.4) * fl) | 0) % fl;
          }
        }
        const o = this.cardCount * GRASS_BLADE_FLOATS;
        d[o] = bx; d[o + 1] = gy; d[o + 2] = bz; d[o + 3] = hgt;
        d[o + 4] = wdt; d[o + 5] = rand2(wcz * 3.7, wcx) * 6.28318; d[o + 6] = 1; d[o + 7] = frame;
        d[o + 8] = r; d[o + 9] = g; d[o + 10] = bl; d[o + 11] = 0;
        this.cardCount++;
        if (this.cardCount >= MAX_CARDS) return;
      }
    }
  }

  /** Draw the packed blades — inside the OPAQUE pass (depth write on, cull
   * off; blades are double-sided). Returns draws issued. */
  draw(frame: GrassFrameU): number {
    const gl = this.gl;
    if (!this.prog.p || this.count === 0) return 0;
    gl.useProgram(this.prog.p);
    const u = this.prog.u;
    if (u.uViewProj) gl.uniformMatrix4fv(u.uViewProj, false, frame.vp);
    if (u.uCamPos) gl.uniform4fv(u.uCamPos, frame.camPos as Float32List);
    if (u.uFogColor) gl.uniform4fv(u.uFogColor, frame.fogColor as Float32List);
    if (u.uParams) gl.uniform4fv(u.uParams, frame.params as Float32List);
    if (u.uLightDir) gl.uniform4fv(u.uLightDir, frame.lightDir as Float32List);
    if (u.uAmbSky) gl.uniform4fv(u.uAmbSky, frame.ambSky as Float32List);
    if (u.uAmbGround) gl.uniform4fv(u.uAmbGround, frame.ambGround as Float32List);
    if (u.uSunCol) gl.uniform4fv(u.uSunCol, frame.sunCol as Float32List);
    if (u.uWind) {
      gl.uniform4f(u.uWind, Math.cos(this.windDir), Math.sin(this.windDir), this.windStr, this.dryness);
    }
    if (!this.vao) this.vao = gl.createVertexArray();
    gl.bindVertexArray(this.vao);
    this.inst.upload(this.data, this.count * GRASS_BLADE_FLOATS);
    instanceVec4Attribs(gl, 0, 3);
    gl.disable(gl.CULL_FACE);           // double-sided blades
    gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, GRASS_BLADE_VERTS, this.count);
    gl.enable(gl.CULL_FACE);
    gl.bindVertexArray(null);
    return 1 + this.drawCards(frame);
  }

  /** Draw the far cards — cardRenderWGSL's pass (Y-billboards, alpha test,
   * depth write on, cull off), sharing the frame uniforms. */
  private drawCards(frame: GrassFrameU): number {
    const gl = this.gl;
    if (!this.cardProg.p || !this.cardTex || this.cardCount === 0) return 0;
    gl.useProgram(this.cardProg.p);
    const u = this.cardProg.u;
    if (u.uViewProj) gl.uniformMatrix4fv(u.uViewProj, false, frame.vp);
    if (u.uCamPos) gl.uniform4fv(u.uCamPos, frame.camPos as Float32List);
    if (u.uFogColor) gl.uniform4fv(u.uFogColor, frame.fogColor as Float32List);
    if (u.uParams) gl.uniform4fv(u.uParams, frame.params as Float32List);
    if (u.uLightDir) gl.uniform4fv(u.uLightDir, frame.lightDir as Float32List);
    if (u.uAmbSky) gl.uniform4fv(u.uAmbSky, frame.ambSky as Float32List);
    if (u.uAmbGround) gl.uniform4fv(u.uAmbGround, frame.ambGround as Float32List);
    if (u.uSunCol) gl.uniform4fv(u.uSunCol, frame.sunCol as Float32List);
    if (u.uRight) gl.uniform4fv(u.uRight, frame.right as Float32List);
    if (u.uWind) gl.uniform4f(u.uWind, Math.cos(this.windDir), Math.sin(this.windDir), this.windStr, this.dryness);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D_ARRAY, this.cardTex);
    if (!this.cardVao) this.cardVao = gl.createVertexArray();
    gl.bindVertexArray(this.cardVao);
    this.cardInst.upload(this.cardData, this.cardCount * GRASS_BLADE_FLOATS);
    instanceVec4Attribs(gl, 0, 3);
    gl.disable(gl.CULL_FACE);
    gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, this.cardCount);
    gl.enable(gl.CULL_FACE);
    gl.bindVertexArray(null);
    return 1;
  }

  destroy(): void { this.dead = true; }
}
