// VOXELS on the WebGL fallback — the GL twin of voxel3d.ts's Voxels3d. The
// whole voxel FEATURE is CPU (VoxelWorld grid, exposed-face mesher + baked
// AO, DDA raycast, terrain generation, VoxelBody/VoxelAgent controllers) and
// is REUSED verbatim from voxel3d.ts; only the thin GPU layer is re-plumbed:
//   - the procedural tile pack (bakeTiles) uploads into a TEXTURE_2D_ARRAY
//     (sRGB + CPU-halved mips via halveRGBA — one tile per layer, so mips
//     never bleed across tiles), instead of a WebGPU texture_2d_array;
//   - chunk meshes become per-chunk VBOs (VOX_FLOATS = 8 stride) drawn with
//     the VOXEL_WGSL port in shaders3d.ts (buildGlVoxelVert/FragGLSL);
//   - the shared frame uniforms arrive as plain uniforms per draw call.
// Drawn inside GlWorld3d's OPAQUE pass (depth write on, back-cull, alpha
// cutout in-shader), distance-culled per chunk against the live camera —
// exactly the original's render() logic.
//
// Module load is DOM/GL-free.

import {
  VoxelWorld, bakeTiles, halveRGBA, meshChunk, raycastVoxel, voxelTerrain,
  VOX_FLOATS, type VoxelOptions, type VoxelTerrainOptions, type VoxelHit,
} from '../voxel3d.js';
import { compileProgram } from '../webgl/shaders.js';
import { buildGlVoxelVertGLSL, buildGlVoxelFragGLSL } from './shaders3d.js';

/** The per-frame uniform values the voxel program consumes (a subset of the
 * world's shared frame bundle — world.ts passes its FrameU straight in). */
export interface VoxelFrameU {
  vp: Float32Array;
  camPos: readonly number[];
  fogColor: readonly number[];
  params: readonly number[];
  ambSky: readonly number[];
  ambGround: readonly number[];
  sunCol: readonly number[];
}

interface ChunkBuf { vbuf: WebGLBuffer | null; count: number }

/** The renderable voxel world on the GL backend. `world.voxels()` builds it;
 * edit via set/get, pick with `raycast`; GlWorld3d draws it in-pass. */
export class GlVoxels3d {
  readonly world: VoxelWorld;
  readonly blockSize: number;
  private gl!: WebGL2RenderingContext;
  private bufs: ChunkBuf[];
  private prog: WebGLProgram | null = null;
  private u: Record<string, WebGLUniformLocation | null> = {};
  private vao: WebGLVertexArrayObject | null = null;
  private atlasTex: WebGLTexture | null = null;
  private readonly tileRes: number;
  private readonly seed: number;
  private readonly mip: boolean;
  private cullDist: number;

  constructor(
    gl: WebGL2RenderingContext,
    private camera: { x: number; y: number; z: number },
    opts: VoxelOptions = {},
  ) {
    this.world = new VoxelWorld(opts);
    this.blockSize = opts.blockSize ?? 1;
    this.tileRes = opts.tileRes ?? 16;
    this.seed = opts.seed ?? 1;
    this.mip = opts.mipmaps ?? true;
    this.cullDist = opts.cullDist ?? 512;
    this.bufs = Array.from({ length: this.world.chunkCount }, () => ({ vbuf: null, count: 0 }));
    this.rebuild(gl);
  }

  /** (Re)create every GL object from CPU state — context-restore path. */
  rebuild(gl: WebGL2RenderingContext): void {
    this.gl = gl;
    this.bufs = Array.from({ length: this.world.chunkCount }, () => ({ vbuf: null, count: 0 }));
    this.vao = null;
    this.prog = compileProgram(gl, buildGlVoxelVertGLSL(), buildGlVoxelFragGLSL(), 'GlVoxels3d');
    this.u = {};
    if (this.prog) {
      for (const name of ['uViewProj', 'uCamPos', 'uFogColor', 'uParams', 'uAmbSky', 'uAmbGround', 'uSunCol']) {
        this.u[name] = gl.getUniformLocation(this.prog, name);
      }
      gl.useProgram(this.prog);
      const loc = gl.getUniformLocation(this.prog, 'uAtlas');
      if (loc) gl.uniform1i(loc, 0);
    }
    this.uploadAtlas();
    this.world.markAllDirty();
  }

  /** Bake + upload the procedural tile pack into a 2D ARRAY texture with a
   * CPU-halved mip chain (the WebGPU uploadAtlas recipe, texSubImage3D-ed). */
  private uploadAtlas(): void {
    const gl = this.gl, res = this.tileRes;
    const { data, layers } = bakeTiles(res, this.seed);
    const mipCount = this.mip ? 1 + Math.floor(Math.log2(res)) : 1;
    if (this.atlasTex) gl.deleteTexture(this.atlasTex);
    this.atlasTex = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D_ARRAY, this.atlasTex);
    gl.texStorage3D(gl.TEXTURE_2D_ARRAY, mipCount, gl.SRGB8_ALPHA8, res, res, layers);
    for (let l = 0; l < layers; l++) {
      let px = data.subarray(l * res * res * 4, (l + 1) * res * res * 4) as Uint8Array<ArrayBuffer>;
      let w = res, h = res;
      for (let m = 0; m < mipCount; m++) {
        gl.texSubImage3D(gl.TEXTURE_2D_ARRAY, m, 0, 0, l, w, h, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
        if (m + 1 < mipCount) { const n = halveRGBA(px, w, h); px = n.px as Uint8Array<ArrayBuffer>; w = n.w; h = n.h; }
      }
    }
    // Crisp block texels up close; mips (linear) kill distant shimmer.
    gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_MIN_FILTER, this.mip ? gl.LINEAR_MIPMAP_LINEAR : gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_WRAP_S, gl.REPEAT);
    gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_WRAP_T, gl.REPEAT);
  }

  // ── Editing / queries (delegate to the shared CPU model) ──
  get(x: number, y: number, z: number): number { return this.world.get(x, y, z); }
  set(x: number, y: number, z: number, id: number): void { this.world.set(x, y, z, id); }

  /** Author the world in bulk: `(x,y,z) => blockId`. */
  generate(fn: (x: number, y: number, z: number) => number): void {
    const w = this.world;
    for (let y = 0; y < w.sy; y++) for (let z = 0; z < w.sz; z++) for (let x = 0; x < w.sx; x++) {
      const id = fn(x, y, z); if (id) w.set(x, y, z, id);
    }
  }

  /** Build (or REBUILD) a landscape — voxelTerrain over a cleared world. */
  landscape(opts: VoxelTerrainOptions = {}): void {
    this.world.clear();
    voxelTerrain(this.world, opts);
  }

  /** World-space Y (feet) to drop a body/mob at column (x, z). */
  spawnY(x: number, z: number): number {
    return (this.world.columnTop((x / this.blockSize) | 0, (z / this.blockSize) | 0) + 1) * this.blockSize;
  }

  /** DDA raycast in world space → block coords + entry normal (voxel3d.ts). */
  raycast(ox: number, oy: number, oz: number, dx: number, dy: number, dz: number, maxDist = 64): VoxelHit | null {
    const b = this.blockSize;
    return raycastVoxel((x, y, z) => this.world.get(x, y, z), ox / b, oy / b, oz / b, dx, dy, dz, maxDist / b);
  }

  /** Re-mesh dirty chunks + upload their VBOs (budget-capped, like the
   * original's per-frame remeshDirty). */
  remeshDirty(budget = 8): void {
    if (!this.world.dirty.size) return;
    const gl = this.gl, b = this.blockSize, ch = this.world.ch;
    let done = 0;
    for (const idx of this.world.dirty) {
      const [cx, cy, cz] = this.world.chunkCoords(idx);
      const verts = meshChunk((x, y, z) => this.world.get(x, y, z), cx * ch, cy * ch, cz * ch, ch);
      const buf = this.bufs[idx];
      if (verts.length === 0) {
        if (buf.vbuf) gl.deleteBuffer(buf.vbuf);
        buf.vbuf = null; buf.count = 0;
      } else {
        if (b !== 1) for (let i = 0; i < verts.length; i += VOX_FLOATS) { verts[i] *= b; verts[i + 1] *= b; verts[i + 2] *= b; }
        buf.vbuf ??= gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, buf.vbuf);
        gl.bufferData(gl.ARRAY_BUFFER, verts, gl.STATIC_DRAW);
        buf.count = verts.length / VOX_FLOATS;
      }
      this.world.dirty.delete(idx);
      if (++done >= budget) break;
    }
  }

  /** Draw every non-empty, in-range chunk — called by GlWorld3d inside the
   * opaque pass (depth write on, back-cull already set). Returns the number
   * of draw calls issued (for counts.draws). */
  render(frame: VoxelFrameU): number {
    const gl = this.gl;
    if (!this.prog) return 0;
    this.remeshDirty();
    let draws = 0;
    let set = false;
    const b = this.blockSize, ch = this.world.ch, half = (ch * b) * 0.5, cull2 = this.cullDist * this.cullDist;
    for (let idx = 0; idx < this.bufs.length; idx++) {
      const buf = this.bufs[idx];
      if (!buf.vbuf || !buf.count) continue;
      const [cx, cy, cz] = this.world.chunkCoords(idx);
      const dx = (cx * ch * b + half) - this.camera.x;
      const dy = (cy * ch * b + half) - this.camera.y;
      const dz = (cz * ch * b + half) - this.camera.z;
      if (dx * dx + dy * dy + dz * dz > cull2) continue;
      if (!set) {
        gl.useProgram(this.prog);
        const u = this.u;
        if (u.uViewProj) gl.uniformMatrix4fv(u.uViewProj, false, frame.vp);
        if (u.uCamPos) gl.uniform4fv(u.uCamPos, frame.camPos as Float32List);
        if (u.uFogColor) gl.uniform4fv(u.uFogColor, frame.fogColor as Float32List);
        if (u.uParams) gl.uniform4fv(u.uParams, frame.params as Float32List);
        if (u.uAmbSky) gl.uniform4fv(u.uAmbSky, frame.ambSky as Float32List);
        if (u.uAmbGround) gl.uniform4fv(u.uAmbGround, frame.ambGround as Float32List);
        if (u.uSunCol) gl.uniform4fv(u.uSunCol, frame.sunCol as Float32List);
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D_ARRAY, this.atlasTex);
        if (!this.vao) this.vao = gl.createVertexArray();
        gl.bindVertexArray(this.vao);
        set = true;
      }
      gl.bindBuffer(gl.ARRAY_BUFFER, buf.vbuf);
      const stride = VOX_FLOATS * 4;
      gl.enableVertexAttribArray(0);
      gl.vertexAttribPointer(0, 3, gl.FLOAT, false, stride, 0);
      gl.enableVertexAttribArray(1);
      gl.vertexAttribPointer(1, 2, gl.FLOAT, false, stride, 12);
      gl.enableVertexAttribArray(2);
      gl.vertexAttribPointer(2, 1, gl.FLOAT, false, stride, 20);
      gl.enableVertexAttribArray(3);
      gl.vertexAttribPointer(3, 1, gl.FLOAT, false, stride, 24);
      gl.enableVertexAttribArray(4);
      gl.vertexAttribPointer(4, 1, gl.FLOAT, false, stride, 28);
      gl.drawArrays(gl.TRIANGLES, 0, buf.count);
      draws++;
    }
    if (set) gl.bindVertexArray(null);
    return draws;
  }

  /** Live stats for a HUD/debug panel. */
  get stats(): { chunks: number; verts: number } {
    let chunks = 0, verts = 0;
    for (const b of this.bufs) if (b.count) { chunks++; verts += b.count; }
    return { chunks, verts };
  }

  destroy(): void {
    for (const b of this.bufs) if (b.vbuf) this.gl.deleteBuffer(b.vbuf);
    this.bufs = [];
    if (this.atlasTex) this.gl.deleteTexture(this.atlasTex);
    this.atlasTex = null;
  }
}
