// ── The retained handles — duplicated from world3d.ts (pure CPU classes; a
// value import of world3d.js would drag the whole WebGPU 3D core into this
// chunk, which §3.1 forbids). Field-for-field identical, so game code that
// was written against World3d handles works unchanged.

export interface Mesh3dConfig {
  x?: number; y?: number; z?: number;
  w?: number; h?: number; d?: number;
  color?: string;
  yaw?: number; pitch?: number; roll?: number;
  gloss?: number;
  metallic?: number;
  rough?: number;
  alpha?: number;
  texture?: number;
  normalMap?: number;
  tile?: number | { x: number; y: number };
  parent?: Group3d | Mesh3d | null;
  bump?: number;
  emissive?: number;
  blob?: boolean;
  /** Accepted for parity; on the GL fallback static meshes are CPU-packed
   * and CPU-culled like everything else (no GPU cull path). */
  static?: boolean;
}

/** A retained mesh — mutate fields freely; kill() removes it. */
export class Mesh3d {
  x: number; y: number; z: number;
  w: number; h: number; d: number;
  yaw: number; pitch: number; roll: number;
  color: string; alpha: number; gloss: number;
  metallic: number; rough: number | null;
  texture: number;
  normalMap: number;
  tile: number | { x: number; y: number };
  bump: number;
  emissive: number;
  grain: number;
  blob: boolean | undefined;
  readonly static: boolean;
  /** @internal VS-skinning palette slice base (mat4 units). */
  paletteBase = 0;
  parent: Group3d | Mesh3d | null;
  inputEnabled = false;
  dead = false;
  constructor(c: Mesh3dConfig = {}) {
    this.x = c.x ?? 0; this.y = c.y ?? 0; this.z = c.z ?? 0;
    this.w = c.w ?? 1; this.h = c.h ?? 1; this.d = c.d ?? 1;
    this.yaw = c.yaw ?? 0; this.pitch = c.pitch ?? 0; this.roll = c.roll ?? 0;
    this.color = c.color ?? (c.texture != null && c.texture >= 0 ? '#ffffff' : '#8a93b5');
    this.alpha = c.alpha ?? 1;
    this.gloss = c.gloss ?? 0;
    this.metallic = c.metallic ?? 0;
    this.rough = c.rough ?? null;
    this.texture = c.texture ?? -1;
    this.normalMap = c.normalMap ?? -1;
    this.tile = c.tile ?? 1;
    this.bump = c.bump ?? 1;
    this.emissive = c.emissive ?? 0;
    this.grain = 0;
    this.blob = c.blob;
    this.static = c.static ?? false;
    this.parent = c.parent ?? null;
  }
  kill(): void { this.dead = true; }
}

/** @deprecated alias — boxes are just meshes now (World3d parity). */
export const Box3d = Mesh3d;
export type Box3d = Mesh3d;
export type Box3dConfig = Mesh3dConfig;

export interface Group3dConfig {
  x?: number; y?: number; z?: number;
  yaw?: number; pitch?: number; roll?: number;
  scale?: number;
  parent?: Group3d | Mesh3d | null;
}

/** A pure transform node (renders nothing) — parent meshes/models to it. */
export class Group3d {
  x: number; y: number; z: number;
  yaw: number; pitch: number; roll: number;
  scale: number;
  parent: Group3d | Mesh3d | null;
  constructor(c: Group3dConfig = {}) {
    this.x = c.x ?? 0; this.y = c.y ?? 0; this.z = c.z ?? 0;
    this.yaw = c.yaw ?? 0; this.pitch = c.pitch ?? 0; this.roll = c.roll ?? 0;
    this.scale = c.scale ?? 1;
    this.parent = c.parent ?? null;
  }
  /** Aim this node's local +Z at a world point (sets yaw + pitch). */
  lookAt(x: number, y: number, z: number): void {
    const e = lookAtEuler(this.x, this.y, this.z, x, y, z);
    this.yaw = e.yaw;
    this.pitch = e.pitch;
  }
}

