// WATER on the WebGL fallback — the GL twin of water3d.ts's Water3dLayer.
// The CPU half is REUSED WHOLESALE from water3d.ts (it never touches the
// device): the Water3d handle (presets, tints, swell/tide dials, wells and —
// critically — the `heightAt` CPU wave replica, so GPU surface and gameplay
// stay single-sourced), plus bakeRippleField for the ripple texture. This
// file re-plumbs only the GPU half:
//   - the two painter's-order warped grids (fine 288 / coarse 96, outer
//     rings first — the compositing fix behind "Rich's teeth") + ribbon VBOs;
//   - per-water params as ONE `uniform vec4 uWP[32]` upload (the WP struct
//     float-for-float — see buildGlWaterVertGLSL's header);
//   - the baked terrain-ground R32F texture (exact shoaling/swash) and the
//     baked tileable ripple field with CPU-halved mips;
//   - the FOAM STAMP buffer (hull wakes): decay+diffuse+stamp into an R8
//     ping-pong — a texture SWAP replaces the WebGPU copy-back;
//   - scene-depth reads ride the world's DEPTH COPY (the seam pattern).
// Drawn at the head of pass B (after blob shadows, before translucent
// meshes), premultiplied, depth-tested read-only, cull off — the original's
// pipeline state exactly.
//
// Module load is DOM/GL-free.

import { Water3d, bakeRippleField } from '../water3d.js';
import { rgba } from '../color.js';
import { compileProgram } from '../webgl/shaders.js';
import {
  buildGlWaterVertGLSL, buildGlWaterFragGLSL,
  buildGlFoamDecayFragGLSL, buildGlFoamStampVertGLSL, buildGlFoamStampFragGLSL,
  buildGlFullscreenVertGLSL,
} from './shaders3d.js';
import type { WaterWell } from '../water3d.js';

const WP_FLOATS = 128;   // 32 vec4 — the WebGPU WP struct, float-for-float
const GRID_FINE = 288;
const GRID_COARSE = 96;
const GRID_SPLIT = 900;
const FOAM_RES = 512;
const FOAM_SPAN = 360;

/** The per-frame uniform values the water programs consume (the world's
 * FrameU is structurally a superset — world.ts passes it straight in). */
export interface WaterFrameU {
  vp: Float32Array;
  camPos: readonly number[];
  fogColor: readonly number[];
  params: readonly number[];
  lightDir: readonly number[];
  ambSky: readonly number[];
  ambGround: readonly number[];
  sunCol: readonly number[];
}

interface WProg { p: WebGLProgram | null; u: Record<string, WebGLUniformLocation | null> }

interface WaterRec {
  wp: Float32Array;
  vbuf: WebGLBuffer | null;       // ribbon strip
  vertCount: number;
  groundTex: WebGLTexture | null; // baked terrain heights (R32F)
  groundSize: number;             // texels per side (0 = none)
}

export class GlWaterLayer {
  private gl!: WebGL2RenderingContext;
  private gridProg: WProg = { p: null, u: {} };
  private ribbonProg: WProg = { p: null, u: {} };
  private decayProg: WProg = { p: null, u: {} };
  private stampProg: WProg = { p: null, u: {} };
  private vao: WebGLVertexArrayObject | null = null;
  private fsVao: WebGLVertexArrayObject | null = null;
  private gridVbufFine: WebGLBuffer | null = null;
  private gridVbufCoarse: WebGLBuffer | null = null;
  private gridVertsFine = 0;
  private gridVertsCoarse = 0;
  private rippleTex: WebGLTexture | null = null;
  private dummyGround: WebGLTexture | null = null;
  private foamA: { fbo: WebGLFramebuffer; tex: WebGLTexture } | null = null;
  private foamB: { fbo: WebGLFramebuffer; tex: WebGLTexture } | null = null;
  private foamOrigin: [number, number] = [1e9, 1e9];
  private wellPrev = new WeakMap<WaterWell, [number, number]>();
  private stampData = new Float32Array(32);
  private gpu = new Map<Water3d, WaterRec>();

  constructor(gl: WebGL2RenderingContext) {
    this.rebuild(gl);
  }

  /** (Re)create every GL object — context-restore path (per-water records
   * recreate lazily, incl. the ground re-bake from the live ground fn). */
  rebuild(gl: WebGL2RenderingContext): void {
    this.gl = gl;
    this.gpu.clear();
    this.vao = null;
    this.fsVao = null;
    this.foamOrigin = [1e9, 1e9];
    const waterU = [
      'uWP', 'uViewProj', 'uCamPos', 'uFogColor', 'uParams', 'uLightDir',
      'uAmbSky', 'uAmbGround', 'uSunCol', 'uLights', 'uLightCount',
    ];
    const waterSamp = { uEnv: 0, uDepth: 1, uGround: 2, uRipple: 3, uFoam: 4 };
    const make = (vs: string, fs: string, label: string, uniforms: string[], samplers: Record<string, number>): WProg => {
      const p = compileProgram(gl, vs, fs, label);
      const u: Record<string, WebGLUniformLocation | null> = {};
      if (p) {
        for (const name of uniforms) u[name] = gl.getUniformLocation(p, name);
        gl.useProgram(p);
        for (const [name, unit] of Object.entries(samplers)) {
          const loc = gl.getUniformLocation(p, name);
          if (loc) gl.uniform1i(loc, unit);
        }
      }
      return { p, u };
    };
    const waterFs = buildGlWaterFragGLSL();
    this.gridProg = make(buildGlWaterVertGLSL(true), waterFs, 'GlWaterLayer grid', waterU, waterSamp);
    this.ribbonProg = make(buildGlWaterVertGLSL(false), waterFs, 'GlWaterLayer ribbon', waterU, waterSamp);
    this.decayProg = make(buildGlFullscreenVertGLSL(), buildGlFoamDecayFragGLSL(), 'GlWaterLayer foam decay', ['uShift'], { uSrc: 0 });
    this.stampProg = make(buildGlFoamStampVertGLSL(), buildGlFoamStampFragGLSL(), 'GlWaterLayer foam stamp', ['uStamps'], {});

    // The two shared unit grids, PAINTER'S ORDER (outer rings first): water
    // draws depth-write-off, so overlapping water fragments composite in
    // triangle order — the camera-centred warp makes ring distance == view
    // distance, so outer-first is exactly far-to-near (the teeth fix).
    const buildGrid = (RES: number): WebGLBuffer => {
      const g = new Float32Array(RES * RES * 6 * 2);
      let o = 0;
      const cells: Array<[number, number]> = [];
      for (let iz = 0; iz < RES; iz++) for (let ix = 0; ix < RES; ix++) cells.push([ix, iz]);
      const ring = (c: [number, number]): number =>
        Math.max(Math.abs(c[0] + 0.5 - RES / 2), Math.abs(c[1] + 0.5 - RES / 2));
      cells.sort((a, b) => ring(b) - ring(a));
      for (const [ix, iz] of cells) {
        const x0 = ix / RES - 0.5, x1 = (ix + 1) / RES - 0.5;
        const z0 = iz / RES - 0.5, z1 = (iz + 1) / RES - 0.5;
        g[o++] = x0; g[o++] = z0; g[o++] = x0; g[o++] = z1; g[o++] = x1; g[o++] = z0;
        g[o++] = x1; g[o++] = z0; g[o++] = x0; g[o++] = z1; g[o++] = x1; g[o++] = z1;
      }
      const buf = gl.createBuffer()!;
      gl.bindBuffer(gl.ARRAY_BUFFER, buf);
      gl.bufferData(gl.ARRAY_BUFFER, g, gl.STATIC_DRAW);
      return buf;
    };
    this.gridVbufFine = buildGrid(GRID_FINE);
    this.gridVertsFine = GRID_FINE * GRID_FINE * 6;
    this.gridVbufCoarse = buildGrid(GRID_COARSE);
    this.gridVertsCoarse = GRID_COARSE * GRID_COARSE * 6;

    // The baked ripple field with a CPU box-filtered mip chain (the encode is
    // affine, so averaging bytes IS averaging the field — water3d's recipe).
    {
      const RS = 512;
      const mips = 1 + Math.log2(RS);
      if (this.rippleTex) gl.deleteTexture(this.rippleTex);
      this.rippleTex = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, this.rippleTex);
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
      gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
      let level = bakeRippleField(RS);
      let w = RS;
      for (let m = 0; m < mips; m++) {
        gl.texImage2D(gl.TEXTURE_2D, m, gl.RGBA8, w, w, 0, gl.RGBA, gl.UNSIGNED_BYTE, level);
        if (m + 1 < mips) {
          const hw = w >> 1;
          const next = new Uint8Array(hw * hw * 4);
          for (let y = 0; y < hw; y++) {
            for (let x = 0; x < hw; x++) {
              for (let c = 0; c < 4; c++) {
                const i0 = (y * 2 * w + x * 2) * 4 + c, i1 = i0 + w * 4;
                next[(y * hw + x) * 4 + c] = (level[i0] + level[i0 + 4] + level[i1] + level[i1 + 4] + 2) >> 2;
              }
            }
          }
          level = next; w = hw;
        }
      }
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.REPEAT);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.REPEAT);
    }
    // 1×1 “no ground” stand-in (-1000 = seabed far below everything).
    this.dummyGround = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, this.dummyGround);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.R32F, 1, 1, 0, gl.RED, gl.FLOAT, new Float32Array([-1000]));
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    // The foam stamp ping-pong (R8, linear clamp).
    const mkFoam = (): { fbo: WebGLFramebuffer; tex: WebGLTexture } => {
      const tex = gl.createTexture()!;
      gl.bindTexture(gl.TEXTURE_2D, tex);
      gl.texStorage2D(gl.TEXTURE_2D, 1, gl.R8, FOAM_RES, FOAM_RES);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      const fbo = gl.createFramebuffer()!;
      gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
      gl.clearColor(0, 0, 0, 1);
      gl.clear(gl.COLOR_BUFFER_BIT);
      return { fbo, tex };
    };
    this.foamA = mkFoam();
    this.foamB = mkFoam();
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  }

  /** The FOAM STAMP pass — decay+diffuse last frame (camera-shifted) into
   * the other target, stamp every well (intensity rides its speed), SWAP.
   * Runs before the main passes; restores the caller's FBO + viewport. */
  foamPass(
    waters: Water3d[], eyeX: number, eyeZ: number, dt: number,
    restoreFbo: WebGLFramebuffer | null, width: number, height: number,
  ): void {
    const gl = this.gl;
    if (!this.decayProg.p || !this.foamA || !this.foamB) return;
    const texel = FOAM_SPAN / FOAM_RES;
    const ox = Math.round(eyeX / texel) * texel;
    const oz = Math.round(eyeZ / texel) * texel;
    const first = this.foamOrigin[0] > 1e8;
    const shiftX = first ? 0 : (ox - this.foamOrigin[0]) / FOAM_SPAN;
    const shiftZ = first ? 0 : (oz - this.foamOrigin[1]) / FOAM_SPAN;
    const decay = first ? 0 : Math.exp(-dt / 2.4);       // froth fades over ~4-5 s
    this.foamOrigin = [ox, oz];
    // Pack the well stamps (max 4; deposition scales WITH SPEED — water3d).
    let nStamps = 0;
    const fd = this.stampData;
    for (const w of waters) {
      if (w.dead || w.kind !== 'grid') continue;
      for (const wl of w.wells) {
        if (wl.dead || nStamps >= 4) continue;
        const prev = this.wellPrev.get(wl);
        const spd = prev ? Math.hypot(wl.x - prev[0], wl.z - prev[1]) / Math.max(dt, 1e-3) : 0;
        this.wellPrev.set(wl, [wl.x, wl.z]);
        const inten = Math.min(0.55, wl.wake * (0.15 + 0.28 * spd) * dt);
        const o = nStamps * 8;
        const back = wl.d * 0.3;
        fd[o] = (wl.x - Math.sin(wl.yaw) * back - ox) / FOAM_SPAN + 0.5;
        fd[o + 1] = (wl.z - Math.cos(wl.yaw) * back - oz) / FOAM_SPAN + 0.5;
        fd[o + 2] = wl.yaw;
        fd[o + 3] = inten;
        fd[o + 4] = (wl.w * 0.38) / FOAM_SPAN;
        fd[o + 5] = (wl.d * 0.3) / FOAM_SPAN;
        nStamps++;
      }
    }
    // Render A → B, then swap (the GL replacement for WebGPU's copy-back).
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.foamB.fbo);
    gl.viewport(0, 0, FOAM_RES, FOAM_RES);
    gl.disable(gl.DEPTH_TEST);
    gl.disable(gl.BLEND);
    gl.clearColor(0, 0, 0, 1);
    gl.clear(gl.COLOR_BUFFER_BIT);
    if (!this.fsVao) this.fsVao = gl.createVertexArray();
    gl.bindVertexArray(this.fsVao);
    gl.useProgram(this.decayProg.p);
    if (this.decayProg.u.uShift) gl.uniform4f(this.decayProg.u.uShift, shiftX, shiftZ, decay, 1 / FOAM_RES);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.foamA.tex);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    if (nStamps > 0 && this.stampProg.p) {
      gl.useProgram(this.stampProg.p);
      if (this.stampProg.u.uStamps) gl.uniform4fv(this.stampProg.u.uStamps, fd);
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE);
      gl.drawArraysInstanced(gl.TRIANGLES, 0, 6, nStamps);
      gl.disable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    }
    gl.bindVertexArray(null);
    const t = this.foamA; this.foamA = this.foamB; this.foamB = t;
    gl.bindFramebuffer(gl.FRAMEBUFFER, restoreFbo);
    gl.viewport(0, 0, width, height);
  }

  /** Pack + draw every live water — Water3dLayer.update()+draw(), GL-side.
   * Caller state: pass B (premultiplied blend, depth test read-only, cull
   * off). Returns the draw-call count. */
  draw(
    waters: Water3d[], frame: WaterFrameU,
    lightData: Float32Array, lightCount: number,
    envTex: WebGLTexture | null, depthTex: WebGLTexture | null, whiteTex: WebGLTexture | null,
    time: number, projA: number, projB: number, width: number, height: number,
  ): number {
    const gl = this.gl;
    if (!this.gridProg.p && !this.ribbonProg.p) return 0;
    // Reap dead records.
    for (const [w, rec] of this.gpu) {
      if (w.dead || !waters.includes(w)) {
        if (rec.vbuf) gl.deleteBuffer(rec.vbuf);
        if (rec.groundTex) gl.deleteTexture(rec.groundTex);
        this.gpu.delete(w);
      }
    }
    let draws = 0;
    if (!this.vao) this.vao = gl.createVertexArray();
    for (const w of waters) {
      if (w.dead) continue;
      let rec = this.gpu.get(w);
      if (!rec) {
        rec = { wp: new Float32Array(WP_FLOATS), vbuf: null, vertCount: this.gridVertsFine, groundTex: null, groundSize: 0 };
        if (w.ribbon) {
          rec.vbuf = gl.createBuffer();
          gl.bindBuffer(gl.ARRAY_BUFFER, rec.vbuf);
          gl.bufferData(gl.ARRAY_BUFFER, w.ribbon, gl.STATIC_DRAW);
          rec.vertCount = w.ribbon.length / 6;
        }
        if (w.ground && w.kind === 'grid') {
          // Bake the terrain once over the water's extent (~4 units/texel,
          // up to 1024 — the zigzag-contour lesson).
          const GS = Math.min(1024, Math.max(128, 1 << Math.ceil(Math.log2(Math.max(w.w, w.d) / 4))));
          const heights = new Float32Array(GS * GS);
          for (let iy = 0; iy < GS; iy++) {
            const wz = w.z + (iy / (GS - 1) - 0.5) * w.d;
            for (let ix = 0; ix < GS; ix++) {
              heights[iy * GS + ix] = w.ground(w.x + (ix / (GS - 1) - 0.5) * w.w, wz);
            }
          }
          rec.groundTex = gl.createTexture();
          gl.bindTexture(gl.TEXTURE_2D, rec.groundTex);
          gl.texImage2D(gl.TEXTURE_2D, 0, gl.R32F, GS, GS, 0, gl.RED, gl.FLOAT, heights);
          gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
          gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
          gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
          gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
          rec.groundSize = GS;
        }
        this.gpu.set(w, rec);
      }
      // ── Pack the WP block — Water3dLayer.update()'s numbers, verbatim
      // (the swell/tide dials flow through the SAME handle methods the CPU
      // heightAt replica uses — single-sourcing by construction). ─────────
      w.timeNow = time;
      const d = rec.wp;
      const sh = rgba(w.shallow), dp = rgba(w.deep), fm = rgba(w.foam);
      const scale = w.waveScale();
      let ampSum = 0;
      for (const wv of w.waves) ampSum += wv.amp * scale.amp;
      d.set([w.x, w.z, w.w, w.d], 0);
      d.set([w.levelNow(), w.alpha, w.ripple, w.absorb], 4);
      d.set([sh[0], sh[1], sh[2], w.foamWidth], 8);
      d.set([dp[0], dp[1], dp[2], 0.42], 12);
      d.set([fm[0], fm[1], fm[2], w.kind === 'ribbon' ? 1 : 0], 16);
      d.set([projA, projB, width, height], 20);
      const crestGate = Math.min(1, Math.max(0, (ampSum - 0.25) / 0.35));
      d.set([w.flow, Math.max(ampSum, 1e-4), crestGate, rec.groundSize], 24);
      d.set([w.debug, Math.max(w.w, w.d) > GRID_SPLIT ? GRID_FINE : GRID_COARSE, this.foamOrigin[0], this.foamOrigin[1]], 28);
      w.wells = w.wells.filter((wl) => !wl.dead);
      for (let i = 0; i < 4; i++) {
        const wl = w.wells[i];
        if (wl) {
          d.set([wl.x, wl.z, wl.yaw, wl.floor], 32 + i * 8);
          d.set([Math.max(wl.w, 0) / 2, Math.max(wl.d, 0) / 2, wl.feather, 1 + wl.wake], 36 + i * 8);
        } else {
          d.set([0, 0, 0, 0], 32 + i * 8);
          d.set([0, 0, 0, 0], 36 + i * 8);
        }
      }
      // steepNorm rides the handle module — same crest fold guard.
      let sSum = 0;
      for (const wv of w.waves) { if (wv.amp >= 1e-5) sSum += Math.min(1.4, wv.steep * scale.steep); }
      const sNorm = sSum > 4.8 ? 4.8 / sSum : 1;
      for (let i = 0; i < 8; i++) {
        const wv = w.waves[i];
        if (wv) {
          d.set([wv.dir.x, wv.dir.z, wv.amp * scale.amp, wv.len], 64 + i * 8);
          d.set([wv.speed * scale.speed, Math.min(1.4, wv.steep * scale.steep) * sNorm, 0, 0], 68 + i * 8);
        } else {
          d.set([0, 0, 0, 1], 64 + i * 8);
          d.set([0, 0, 0, 0], 68 + i * 8);
        }
      }
      // ── Draw. ─────────────────────────────────────────────────────────
      const prog = w.kind === 'grid' ? this.gridProg : this.ribbonProg;
      if (!prog.p) continue;
      gl.useProgram(prog.p);
      const u = prog.u;
      if (u.uWP) gl.uniform4fv(u.uWP, d);
      if (u.uViewProj) gl.uniformMatrix4fv(u.uViewProj, false, frame.vp);
      if (u.uCamPos) gl.uniform4fv(u.uCamPos, frame.camPos as Float32List);
      if (u.uFogColor) gl.uniform4fv(u.uFogColor, frame.fogColor as Float32List);
      if (u.uParams) gl.uniform4fv(u.uParams, frame.params as Float32List);
      if (u.uLightDir) gl.uniform4fv(u.uLightDir, frame.lightDir as Float32List);
      if (u.uAmbSky) gl.uniform4fv(u.uAmbSky, frame.ambSky as Float32List);
      if (u.uAmbGround) gl.uniform4fv(u.uAmbGround, frame.ambGround as Float32List);
      if (u.uSunCol) gl.uniform4fv(u.uSunCol, frame.sunCol as Float32List);
      if (u.uLights) gl.uniform4fv(u.uLights, lightData);
      if (u.uLightCount) gl.uniform1f(u.uLightCount, lightCount);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, envTex ?? whiteTex);
      gl.activeTexture(gl.TEXTURE1);
      gl.bindTexture(gl.TEXTURE_2D, depthTex ?? whiteTex);
      gl.activeTexture(gl.TEXTURE2);
      gl.bindTexture(gl.TEXTURE_2D, rec.groundTex ?? this.dummyGround);
      gl.activeTexture(gl.TEXTURE3);
      gl.bindTexture(gl.TEXTURE_2D, this.rippleTex);
      gl.activeTexture(gl.TEXTURE4);
      gl.bindTexture(gl.TEXTURE_2D, this.foamA!.tex);
      gl.bindVertexArray(this.vao);
      if (w.kind === 'grid') {
        const fine = Math.max(w.w, w.d) > GRID_SPLIT;
        gl.bindBuffer(gl.ARRAY_BUFFER, fine ? this.gridVbufFine : this.gridVbufCoarse);
        gl.enableVertexAttribArray(0);
        gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 8, 0);
        gl.disableVertexAttribArray(1);
        gl.disableVertexAttribArray(2);
        gl.drawArrays(gl.TRIANGLES, 0, fine ? this.gridVertsFine : this.gridVertsCoarse);
      } else if (rec.vbuf) {
        gl.bindBuffer(gl.ARRAY_BUFFER, rec.vbuf);
        gl.enableVertexAttribArray(0);
        gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 24, 0);
        gl.enableVertexAttribArray(1);
        gl.vertexAttribPointer(1, 2, gl.FLOAT, false, 24, 12);
        gl.enableVertexAttribArray(2);
        gl.vertexAttribPointer(2, 1, gl.FLOAT, false, 24, 20);
        gl.drawArrays(gl.TRIANGLES, 0, rec.vertCount);
      }
      gl.bindVertexArray(null);
      draws++;
    }
    return draws;
  }

  get count(): number { return this.gpu.size; }
}
