// UNDERWATER on the WebGL fallback — the GL twin of underwater3d.ts's
// Underwater3dLayer. The CPU pieces are REUSED WHOLESALE (Underwater3d is a
// pure/live handle: submersion hysteresis, per-channel optics, the fog
// retarget, the shaft-ring CPU pack maths; bakeCausticField is the pure
// Hoskins bake). This file re-plumbs the GPU half:
//   - the baked caustic pattern → an RG8 texture with CPU-halved mips
//     (repeat + trilinear) that the MESH fragment min-blends two taps of;
//   - the fullscreen MULTIPLY + ADD composites into the scene FBO, reading
//     the world's depth copy (the SSAO/rays seam pattern);
//   - the ABZU billboard shaft ring → 2 vec4 instance attributes into a
//     half-res R8 target, blur-composited by the ADD draw.
// The shaft-ring instance PACK is duplicated from Underwater3dLayer.pack
// (it interleaves CPU maths with queue writes there; the numbers are
// verbatim — change both together).
//
// Module load is DOM/GL-free.

import { Underwater3d, bakeCausticField } from '../underwater3d.js';
import { rgba } from '../color.js';
import { mat4Inverse, type Mat4 } from '../math3d.js';
import { compileProgram, InstanceBuffer, instanceVec4Attribs } from '../webgl/shaders.js';
import {
  buildGlFullscreenVertGLSL,
  buildGlUnderwaterMulFragGLSL, buildGlUnderwaterAddFragGLSL,
  buildGlShaftVertGLSL, buildGlShaftFragGLSL,
} from './shaders3d.js';

const MAX_SHAFTS = 640;

interface UProg { p: WebGLProgram | null; u: Record<string, WebGLUniformLocation | null> }

/** Stable per-cell hash — underwater3d.ts's cellHash, duplicated (private
 * there). Keeps each ring slot's shaft identical frame to frame. */
function cellHash(ix: number, iz: number, seed: number): number {
  let h = (ix * 374761393 + iz * 668265263 + seed * 1274126177) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h = (h ^ (h >>> 16)) >>> 0;
  return h / 4294967296;
}

export class GlUnderwaterLayer {
  /** Set by pack() each frame; composite() no-ops when off. */
  active = false;
  /** The baked caustic tile (RG8, mipped, repeat) — the mesh FS taps it. */
  causticTex: WebGLTexture | null = null;

  private gl!: WebGL2RenderingContext;
  private mulProg: UProg = { p: null, u: {} };
  private addProg: UProg = { p: null, u: {} };
  private shaftProg: UProg = { p: null, u: {} };
  private fsVao: WebGLVertexArrayObject | null = null;
  private shaftVao: WebGLVertexArrayObject | null = null;
  private shaftInst!: InstanceBuffer;
  private blackTex: WebGLTexture | null = null;   // "no shafts" stand-in (0)
  private shaftTarget: { fbo: WebGLFramebuffer; tex: WebGLTexture } | null = null;
  private shaftW = 0;
  private shaftH = 0;
  private shaftDrawn = false;
  private shaftCount = 0;
  private instData = new Float32Array(MAX_SHAFTS * 8);
  // Packed uniform values (written by pack(), uploaded at draw).
  private invVP = new Float32Array(16);
  private vp = new Float32Array(16);
  private cam: [number, number, number, number] = [0, 0, 0, 0];
  private sigma: [number, number, number, number] = [0, 0, 0, 0];
  private sunSigma: [number, number, number, number] = [0, 0, 0, 0];
  private water: [number, number, number, number] = [0, 0, 0, 0];
  private screen: [number, number, number, number] = [0, 0, 0, 0];
  private sun: [number, number, number, number] = [0, -1, 0, 0];
  private sunColT: [number, number, number, number] = [1, 1, 1, 0];
  private parm: [number, number, number, number] = [0, 0, 0, 0];
  private fade: [number, number, number, number] = [0, 0, 0, 0];

  constructor(gl: WebGL2RenderingContext) {
    this.rebuild(gl);
  }

  rebuild(gl: WebGL2RenderingContext): void {
    this.gl = gl;
    this.fsVao = null;
    this.shaftVao = null;
    this.shaftTarget = null;
    this.shaftW = 0;
    this.shaftH = 0;
    this.shaftInst = new InstanceBuffer(gl);
    const make = (vs: string, fs: string, label: string, uniforms: string[], samplers: Record<string, number>): UProg => {
      const p = compileProgram(gl, vs, fs, label);
      const u: Record<string, WebGLUniformLocation | null> = {};
      if (p) {
        for (const name of uniforms) u[name] = gl.getUniformLocation(p, name);
        gl.useProgram(p);
        for (const [name, unit] of Object.entries(samplers)) {
          const loc = gl.getUniformLocation(p, name);
          if (loc) gl.uniform1i(loc, unit);
        }
      }
      return { p, u };
    };
    const fsVs = buildGlFullscreenVertGLSL();
    const compU = ['uInvVP', 'uCam', 'uSigma', 'uSunSigma', 'uWater', 'uScreen'];
    this.mulProg = make(fsVs, buildGlUnderwaterMulFragGLSL(), 'GlUnderwater mul', compU, { uDepth: 0 });
    this.addProg = make(fsVs, buildGlUnderwaterAddFragGLSL(), 'GlUnderwater add', compU, { uDepth: 0, uShaft: 1 });
    this.shaftProg = make(buildGlShaftVertGLSL(), buildGlShaftFragGLSL(), 'GlUnderwater shafts',
      ['uViewProj', 'uInvVP', 'uCam', 'uSun', 'uSunCol', 'uParm', 'uFade'], { uDepth: 0 });
    this.blackTex = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, this.blackTex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array([0, 0, 0, 255]));
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    // The caustic tile: two independent phases (R/G) with a CPU box-filtered
    // mip chain, quantised value/2 per level (createCausticTexture's recipe).
    const size = 512;
    const mips = 1 + Math.floor(Math.log2(size));
    if (this.causticTex) gl.deleteTexture(this.causticTex);
    this.causticTex = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, this.causticTex);
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
    let fieldR = bakeCausticField(size, 1.0);
    let fieldG = bakeCausticField(size, 3.7);
    let w = size;
    for (let m = 0; m < mips; m++) {
      const bytes = new Uint8Array(w * w * 2);
      for (let i = 0; i < w * w; i++) {
        const r = Math.round(fieldR[i] * 0.5 * 255);
        const g = Math.round(fieldG[i] * 0.5 * 255);
        bytes[i * 2] = r < 0 ? 0 : r > 255 ? 255 : r;
        bytes[i * 2 + 1] = g < 0 ? 0 : g > 255 ? 255 : g;
      }
      gl.texImage2D(gl.TEXTURE_2D, m, gl.RG8, w, w, 0, gl.RG, gl.UNSIGNED_BYTE, bytes);
      if (m + 1 < mips) {
        const hw = w >> 1;
        const nextR = new Float32Array(hw * hw);
        const nextG = new Float32Array(hw * hw);
        for (let y = 0; y < hw; y++) {
          for (let x = 0; x < hw; x++) {
            const i0 = y * 2 * w + x * 2, i1 = i0 + w;
            nextR[y * hw + x] = (fieldR[i0] + fieldR[i0 + 1] + fieldR[i1] + fieldR[i1 + 1]) * 0.25;
            nextG[y * hw + x] = (fieldG[i0] + fieldG[i0 + 1] + fieldG[i1] + fieldG[i1 + 1]) * 0.25;
          }
        }
        fieldR = nextR; fieldG = nextG; w = hw;
      }
    }
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 4);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.REPEAT);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.REPEAT);
  }

  /** Pack this frame's uniforms + the shaft ring from the live handle —
   * Underwater3dLayer.pack()'s maths, verbatim. */
  pack(
    uw: Underwater3d, vp: Mat4, eye: { x: number; y: number; z: number },
    sun: { x: number; y: number; z: number }, sunI: number, time: number, storm: number,
  ): void {
    this.active = uw.active;
    if (!uw.active) return;
    this.vp.set(vp);
    this.invVP.set(mat4Inverse(vp));
    const sig = uw.viewSigma();
    const wc = rgba(uw.fogNow.color);        // depth-darkened murk (not raw waterColor)
    this.cam = [eye.x, eye.y, eye.z, 1];
    this.sigma = [sig[0], sig[1], sig[2], uw.surfaceY];
    const ss = uw.sunSigmaNow();
    this.sunSigma = [ss[0], ss[1], ss[2], uw.fullUnder];
    this.water = [wc[0], wc[1], wc[2], uw.grade];
    const feather = 0.12 + uw.fullUnder * 0.4;
    const meniscus = 0.5 * (1 - uw.fullUnder);
    this.screen = [feather, meniscus, uw.vignette, uw.wobble];
    // Shaft gating: night/storm/horizon/camera-depth ramps (verbatim).
    const sl = Math.hypot(sun.x, sun.y, sun.z) || 1;
    const up = -sun.y / sl;
    const horizonK = Math.min(1, Math.max(0, (up - 0.08) / 0.2));
    const dk = Math.min(1, Math.max(0, (uw.depth - 0.2) / 1.2));
    const depthK = dk * dk * (3 - 2 * dk);
    const clr = Math.min(1, Math.max(0, uw.clarity));
    const dStart = 12 + 12 * clr, dEnd = 30 + 18 * clr;
    const dd = Math.min(1, Math.max(0, (uw.depth - dStart) / (dEnd - dStart)));
    const deepK = 1 - dd * dd * (3 - 2 * dd);
    const shaftI = uw.rays ? uw.rayStrength * Math.max(0, sunI) * horizonK * depthK * deepK * (1 - 0.7 * Math.min(1, storm)) : 0;
    const flatLevel = uw.water && !uw.water.dead ? uw.water.levelNow() : uw.surfaceY;
    const reach = 30 + 14 * clr;
    const radius = Math.max(uw.rayNear, 6);
    const beamSpacing = Math.max(uw.rayGap * 0.12, 1.2);
    const N = Math.min(MAX_SHAFTS, Math.max(24, Math.round((2 * Math.PI * radius) / beamSpacing)));
    const TAU = 2 * Math.PI;
    // Refracted sun-DOWN (Snell steepens the horizontal component).
    const rr = 1 / 1.333;
    const ddx = (sun.x / sl) * rr, ddy = sun.y / sl, ddz = (sun.z / sl) * rr;
    const ddl = Math.hypot(ddx, ddy, ddz) || 1;
    this.sun = [ddx / ddl, ddy / ddl, ddz / ddl, shaftI];
    this.sunColT = [1, 1, 1, time];
    this.parm = [flatLevel, uw.rayBand, uw.sunSigma[1] * 0.6, reach];
    this.fade = [radius * 0.15, 6.0, radius * 1.9, uw.rayFlicker];
    let n = 0;
    if (shaftI > 0.001) {
      const inst = this.instData;
      const groundFn = uw.water && !uw.water.dead && uw.water.ground ? uw.water.ground : null;
      const axisYabs = Math.max(Math.abs(ddy / ddl), 0.25);
      const baseY = flatLevel - uw.rayBand;
      for (let i = 0; i < N; i++) {
        const az = (i / N) * TAU + (cellHash(i, 0, 5) - 0.5) * (TAU / N) * 0.8;
        const rj = radius * (0.85 + 0.3 * cellHash(i, 0, 3));
        const bx = eye.x + Math.cos(az) * rj;
        const bz = eye.z + Math.sin(az) * rj;
        let maxLen = reach;
        if (groundFn) maxLen = (baseY - groundFn(bx, bz) - 5) / axisYabs;
        const len = Math.max(0, Math.min(reach * (0.85 + 0.3 * cellHash(i, 0, 17)), maxLen));
        const o = n * 8;
        inst[o] = bx;
        inst[o + 1] = bz;
        inst[o + 2] = len;
        inst[o + 3] = 0.5 + 0.9 * cellHash(i, 0, 19);
        inst[o + 4] = cellHash(i, 0, 23) * TAU;
        inst[o + 5] = 0.12 + 0.18 * cellHash(i, 0, 29);
        inst[o + 6] = 1.2 + 1.6 * cellHash(i, 0, 31);
        inst[o + 7] = 0;
        n++;
      }
    }
    this.shaftCount = n;
  }

  /** Draw the shaft ring into the half-res R8 target (additive), then
   * restore the caller's FBO + viewport. */
  renderShafts(depthTex: WebGLTexture | null, width: number, height: number, restoreFbo: WebGLFramebuffer | null): void {
    const gl = this.gl;
    this.shaftDrawn = false;
    if (!this.active || !depthTex) return;
    const hw = Math.max(1, width >> 1), hh = Math.max(1, height >> 1);
    if (!this.shaftTarget || this.shaftW !== hw || this.shaftH !== hh) {
      if (this.shaftTarget) { gl.deleteTexture(this.shaftTarget.tex); gl.deleteFramebuffer(this.shaftTarget.fbo); }
      const tex = gl.createTexture()!;
      gl.bindTexture(gl.TEXTURE_2D, tex);
      gl.texStorage2D(gl.TEXTURE_2D, 1, gl.R8, hw, hh);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      const fbo = gl.createFramebuffer()!;
      gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
      this.shaftTarget = { fbo, tex };
      this.shaftW = hw; this.shaftH = hh;
    }
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.shaftTarget.fbo);
    gl.viewport(0, 0, hw, hh);
    gl.disable(gl.DEPTH_TEST);
    gl.clearColor(0, 0, 0, 1);
    gl.clear(gl.COLOR_BUFFER_BIT);
    if (this.shaftCount > 0 && this.shaftProg.p) {
      gl.useProgram(this.shaftProg.p);
      const u = this.shaftProg.u;
      if (u.uViewProj) gl.uniformMatrix4fv(u.uViewProj, false, this.vp);
      if (u.uInvVP) gl.uniformMatrix4fv(u.uInvVP, false, this.invVP);
      if (u.uCam) gl.uniform4fv(u.uCam, this.cam);
      if (u.uSun) gl.uniform4fv(u.uSun, this.sun);
      if (u.uSunCol) gl.uniform4fv(u.uSunCol, this.sunColT);
      if (u.uParm) gl.uniform4fv(u.uParm, this.parm);
      if (u.uFade) gl.uniform4fv(u.uFade, this.fade);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, depthTex);
      if (!this.shaftVao) this.shaftVao = gl.createVertexArray();
      gl.bindVertexArray(this.shaftVao);
      this.shaftInst.upload(this.instData, this.shaftCount * 8);
      instanceVec4Attribs(gl, 0, 2);
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE);
      gl.drawArraysInstanced(gl.TRIANGLES, 0, 6, this.shaftCount);
      gl.disable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
      gl.bindVertexArray(null);
    }
    this.shaftDrawn = true;
    gl.bindFramebuffer(gl.FRAMEBUFFER, restoreFbo);
    gl.viewport(0, 0, width, height);
  }

  /** The two blended fullscreen draws into the (bound) scene FBO — multiply
   * extinction, then add in-scatter/meniscus/shafts. Returns draws issued. */
  composite(depthTex: WebGLTexture | null): number {
    const gl = this.gl;
    if (!this.active || !this.mulProg.p || !this.addProg.p || !depthTex) return 0;
    gl.disable(gl.DEPTH_TEST);
    gl.enable(gl.BLEND);
    if (!this.fsVao) this.fsVao = gl.createVertexArray();
    gl.bindVertexArray(this.fsVao);
    const setU = (prog: UProg): void => {
      const u = prog.u;
      if (u.uInvVP) gl.uniformMatrix4fv(u.uInvVP, false, this.invVP);
      if (u.uCam) gl.uniform4fv(u.uCam, this.cam);
      if (u.uSigma) gl.uniform4fv(u.uSigma, this.sigma);
      if (u.uSunSigma) gl.uniform4fv(u.uSunSigma, this.sunSigma);
      if (u.uWater) gl.uniform4fv(u.uWater, this.water);
      if (u.uScreen) gl.uniform4fv(u.uScreen, this.screen);
    };
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, depthTex);
    // MULTIPLY: out = dst * src.
    gl.useProgram(this.mulProg.p);
    setU(this.mulProg);
    gl.blendFuncSeparate(gl.ZERO, gl.SRC_COLOR, gl.ZERO, gl.ONE);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    // ADD: out = dst + src.
    gl.useProgram(this.addProg.p);
    setU(this.addProg);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, this.shaftDrawn && this.shaftTarget ? this.shaftTarget.tex : this.blackTex);
    gl.blendFuncSeparate(gl.ONE, gl.ONE, gl.ZERO, gl.ONE);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    gl.disable(gl.BLEND);
    gl.bindVertexArray(null);
    return 2;
  }
}
