// TRAILS on the WebGL fallback — the CPU half of world3d.ts's Trail3d /
// resampleTrail, DUPLICATED faithfully (their home module is the WebGPU 3D
// core; a value import would drag it into this chunk). Field-for-field and
// line-for-line identical to the originals so the handles behave the same;
// the rendering half (the TRAIL_WGSL port + the RGBA32F instance-data
// texture) lives in shaders3d.ts + world.ts. Change world3d.ts's copies and
// these together.
//
// Module load is DOM/GL-free.

import type { VfxDef, TrailSparks } from '../vfx.js';
import type { Particles3d } from '../particles3d.js';
import { TRAIL_PTS } from './shaders3d.js';

/**
 * Resample a trail's raw point history (oldest first) into `n` control
 * points HEAD (newest) → TAIL, each xyz + fade k, spaced uniformly in ARC
 * LENGTH — world3d.ts's resampleTrail, verbatim (pure, dist-testable).
 */
export function resampleTrail(
  points: ReadonlyArray<{ x: number; y: number; z: number; age: number }>,
  n: number,
  life: number,
  out?: Float32Array,
  offset = 0,
): Float32Array {
  const o = out ?? new Float32Array(n * 4);
  const m = points.length;
  const acc = new Float64Array(m);
  for (let i = 1; i < m; i++) {
    const a = points[i - 1], b = points[i];
    acc[i] = acc[i - 1] + Math.hypot(b.x - a.x, b.y - a.y, b.z - a.z);
  }
  const total = m ? acc[m - 1] : 0;
  let i0 = m - 1;
  for (let j = 0; j < n; j++) {
    const target = total * (1 - j / (n - 1));  // j 0 = head = newest point
    while (i0 > 0 && acc[i0 - 1] >= target) i0--;
    const i1 = Math.max(0, i0 - 1);
    const seg = acc[i0] - acc[i1];
    const w = seg > 0 ? (acc[i0] - target) / seg : 0;   // 0 at i0 → 1 at i1
    const a = points[i0], b = points[i1];
    const base = offset + j * 4;
    o[base] = a.x + (b.x - a.x) * w;
    o[base + 1] = a.y + (b.y - a.y) * w;
    o[base + 2] = a.z + (b.z - a.z) * w;
    const age = a.age + (b.age - a.age) * w;
    o[base + 3] = Math.max(0, Math.min(1, 1 - age / life));
  }
  return o;
}

export interface Trail3dOptions {
  /** Ribbon width in world units (default: the def's 2D width × 0.1). */
  width?: number;
  /** Seconds a point survives (default: the def's life). */
  life?: number;
  /** Auto-feed from this handle each tick; releases when the target dies. */
  follow?: { x: number; y: number; z: number; dead?: boolean } | null;
  /** Feed offset from the followed handle. */
  offset?: { x?: number; y?: number; z?: number };
  /** Min distance between recorded points (default width × 0.5). */
  spacing?: number;
  /** Override the auto-generated tileable noise frame. */
  noiseFrame?: number;
  /** 'view' (camera-facing ribbon) or 'up' (the Tron wall). */
  facing?: 'view' | 'up';
}

/** A live 3D trail — feed `point(x, y, z)` per frame (or pass `follow`).
 * All style fields live-mutable. world3d.ts's Trail3d, duplicated. */
export class Trail3d {
  width: number;
  life: number;
  colors: string[];
  add: boolean;
  taper: boolean;
  alpha: number;
  turbulence: number;
  erode: number;
  core: number;
  fiber: number;
  hard: number;
  /** Electric glint inside the ribbon 0..1 — live-mutable like the rest. */
  crackle: number;
  facing: 'view' | 'up';
  spacing: number;
  follow: { x: number; y: number; z: number; dead?: boolean } | null;
  offset: { x: number; y: number; z: number };
  /** The tileable noise frame driving flutter + erosion. */
  frame: number;
  /** @internal */ seed: number;
  /** @internal */ points: Array<{ x: number; y: number; z: number; age: number }> = [];
  /** @internal */ dead = false;
  // The LIVE head — every point() call lands here exactly; `spacing` only
  // gates what enters the committed history.
  /** @internal */ hx = 0; /** @internal */ hy = 0; /** @internal */ hz = 0;
  /** @internal */ hasHead = false;
  /** @internal Total distance travelled — the noise pattern's world anchor. */
  dist = 0;
  /** @internal Spark shedding pool (wired by world.trail()). */
  fx: Particles3d | null = null;
  private readonly sparks: TrailSparks | null;
  private shedAcc = 0;

  /** @internal — create via world.trail(). */
  constructor(def: VfxDef, frame: number, opts: Trail3dOptions, seed: number) {
    const t = def.trail ?? {};
    this.width = opts.width ?? (t.width ?? 8) * 0.1;
    this.life = opts.life ?? t.life ?? 0.5;
    this.colors = [...(t.colors ?? ['#ffffff'])];
    this.add = t.add ?? false;
    this.taper = t.taper ?? true;
    this.alpha = t.alpha ?? 0.8;
    this.turbulence = t.turbulence ?? 0.35;
    this.erode = t.erode ?? 0.55;
    this.core = t.core ?? 0.5;
    this.fiber = t.fiber ?? 1;
    this.hard = t.hard ?? 0;
    this.crackle = t.crackle ?? 0;
    this.sparks = t.sparks ?? null;
    this.facing = opts.facing ?? t.facing ?? 'view';
    this.spacing = opts.spacing ?? Math.max(0.02, this.width * 0.25);
    this.follow = opts.follow ?? null;
    this.offset = { x: opts.offset?.x ?? 0, y: opts.offset?.y ?? 0, z: opts.offset?.z ?? 0 };
    this.frame = frame;
    this.seed = seed;
  }

  /** Record the head position for this frame. */
  point(x: number, y: number, z: number): void {
    if (this.hasHead) {
      const seg = Math.hypot(x - this.hx, y - this.hy, z - this.hz);
      this.dist += seg;
      // Sparks shed ARC-SPACED along the swept path (2D def numbers scale
      // by the 0.1 trail-width convention — shed rate by ×10).
      if (this.sparks && this.fx && seg > 0) {
        const s = this.sparks;
        const step = 0.1 / (s.per ?? 0.25);
        const dx = (x - this.hx) / seg, dy = (y - this.hy) / seg, dz = (z - this.hz) / seg;
        let travelled = this.shedAcc + seg;
        while (travelled >= step) {
          travelled -= step;
          const along = seg - travelled;
          this.fx.emit({
            x: this.hx + dx * along, y: this.hy + dy * along, z: this.hz + dz * along,
            count: 1,
            speed: (s.speed ?? 30) * 0.1, speedVar: (s.speed ?? 30) * 0.05,
            life: s.life ?? 0.45, lifeVar: (s.life ?? 0.45) * 0.3,
            size: (s.size ?? 2) * 0.1, sizeVar: (s.size ?? 2) * 0.04,
            colors: s.ramp ? undefined : (s.colors ?? this.colors),
            ramp: s.ramp,
            add: s.add ?? this.add,
            gravity: (s.gravity ?? 0) * 0.1,
            drag: s.drag ?? 1.5,
            twinkle: s.twinkle ?? 0.6,
          });
        }
        this.shedAcc = travelled;
      }
    }
    this.hx = x; this.hy = y; this.hz = z; this.hasHead = true;
    const last = this.points[this.points.length - 1];
    if (last && Math.hypot(x - last.x, y - last.y, z - last.z) < this.spacing) return;
    this.points.push({ x, y, z, age: 0 });
  }

  /** Stop feeding; the ribbon fades out, then auto-removes. */
  release(): void {
    this.dead = true;
    this.follow = null;
  }

  /** @internal Age/expire points. Returns true while anything remains. */
  update(dt: number): boolean {
    if (this.follow?.dead) this.release();
    for (const p of this.points) p.age += dt;
    while (this.points.length && this.points[0].age >= this.life) this.points.shift();
    return this.points.length > 0 || !this.dead;
  }

  /** @internal Feed from the followed handle's CURRENT position — called at
   * render time, after the game has moved the handle this frame. */
  feedFollow(): void {
    if (this.follow && !this.dead) {
      this.point(this.follow.x + this.offset.x, this.follow.y + this.offset.y, this.follow.z + this.offset.z);
    }
  }

  /** @internal True once there is enough to draw a ribbon. */
  get ready(): boolean {
    return this.points.length >= 2 || (this.points.length === 1 && this.hasHead);
  }

  /** @internal Resample history + the live head into `out` at `offset`;
   * returns the resampled path's arc length. */
  pack(out: Float32Array, offset: number): number {
    let pts: ReadonlyArray<{ x: number; y: number; z: number; age: number }> = this.points;
    const last = pts[pts.length - 1];
    if (this.hasHead && last && (last.x !== this.hx || last.y !== this.hy || last.z !== this.hz)) {
      pts = [...pts, { x: this.hx, y: this.hy, z: this.hz, age: 0 }];
    }
    resampleTrail(pts, TRAIL_PTS, this.life, out, offset);
    let span = 0;
    for (let i = 1; i < pts.length; i++) {
      const a = pts[i - 1], b = pts[i];
      span += Math.hypot(b.x - a.x, b.y - a.y, b.z - a.z);
    }
    return span;
  }
}
